    ```
    {
      "readme": ...,
      "outputs": [
        {
          "name": "rds_hostname",
          "type": "dynamic",
          "description": "RDS instance hostname"
        },
        {
          "name": "rds_port",
          "type": "dynamic",
          "description": "RDS instance port"
        },
        {
          "name": "rds_username",
          "type": "dynamic",
          "description": "RDS instance root username"
        }
      ],
      "variables": [
        {
          "name": "region",
          "type": "string",
          "default": "ap-northeast-1"
